68	func run(args []string, stdout, stderr io.Writer) int {
69		if len(args) == 0 {
70			printHelp(stdout)
71			return 0
72		}
73		switch args[0] {
74		case "--help", "-h", "help":
75			if len(args) > 1 {
76				fmt.Fprintf(stderr, "%s: help 不接受额外参数\n", appName)
77				return 2
78			}
79			printHelp(stdout)
80			return 0
81		}
82	
83		var err error
84		switch args[0] {
85		case "register":
86			err = cmdRegister(args[1:], stdout)
87		case "list":
88			err = cmdList(args[1:], stdout)
89		case "detail":
90			err = cmdDetail(args[1:], stdout)
91		case "report":
92			err = cmdReport(args[1:], stdout)
93		case "close":
94			err = cmdClose(args[1:], stdout)
95		case "history":
96			err = cmdHistory(args[1:], stdout)
97		default:
98			fmt.Fprintf(stderr, "%s: 未知命令 %q，使用 --help 查看帮助\n", appName, args[0])
99			return 2
100		}
101		if err != nil {
102			if errors.Is(err, flag.ErrHelp) {
103				return 0
104			}
105			var ue *usageError
106			if errors.As(err, &ue) {
107				fmt.Fprintf(stderr, "%s: %s\n", appName, ue.Error())
108				return 2
109			}
110			fmt.Fprintf(stderr, "%s: %s\n", appName, friendlyErr(err.Error()))
111			return 1
112		}
113		return 0
114	}
115	
116	// friendlyErr 去掉内部哨兵错误（errNotFound/errConflict）的英文前缀。
117	func friendlyErr(msg string) string {
118		for _, p := range []string{"not found: ", "conflict: "} {
119			if strings.HasPrefix(msg, p) {
120				return msg[len(p):]
121			}
122		}
123		return msg
124	}
125	
126	type usageError struct{ msg string }
127	
128	func (e *usageError) Error() string { return e.msg }
129	
130	// newFlagSet 为子命令准备参数解析器：--help/-h 输出帮助并返回 flag.ErrHelp，
131	// 其余参数错误转成 *usageError（退出码 2）。
132	func newFlagSet(name string, opts *cmdOptions) *flag.FlagSet {
133		fs := flag.NewFlagSet(name, flag.ContinueOnError)
134		fs.SetOutput(os.Stdout)
135		fs.Usage = func() {
136			fmt.Fprintf(os.Stdout, "用法: caretrack %s [参数]\n\n", name)
137			fs.PrintDefaults()
138		}
139		fs.StringVar(&opts.dataDir, "data-dir", ".caretrack", "本地数据目录")
140		return fs
141	}
142	
143	func parseFlags(fs *flag.FlagSet, args []string) error {
144		if err := fs.Parse(args); err != nil {
145			if errors.Is(err, flag.ErrHelp) {
146				return err
147			}
148			return &usageError{msg: err.Error()}
149		}
150		if fs.NArg() > 0 {
151			return &usageError{msg: fmt.Sprintf("命令 %s 不接受位置参数: %v", fs.Name(), fs.Args())}
152		}
153		return nil
154	}
155	
156	func requireFlag(fs *flag.FlagSet, value, flagName string) error {
157		if value == "" {
158			return &usageError{msg: fmt.Sprintf("命令 %s 缺少必填参数 --%s", fs.Name(), flagName)}
159		}
160		return nil
161	}
