170		if err := parseFlags(fs, args); err != nil {
171			return err
172		}
173		if err := requireFlag(fs, id, "asset-id"); err != nil {
174			return err
175		}
176		if err := requireFlag(fs, name, "name"); err != nil {
177			return err
178		}
179		if err := requireFlag(fs, location, "location"); err != nil {
180			return err
181		}
182	
183		s, err := openStore(opts.dataDir)
184		if err != nil {
185			return err
186		}
187		asset, err := s.registerAsset(id, name, location)
188		if err != nil {
189			return err
190		}
191		if err := s.save(); err != nil {
192			return err
193		}
194		fmt.Fprintf(w, "已登记资产 %s\n", asset.ID)
195		fmt.Fprintf(w, "名称: %s\n", asset.Name)
196		fmt.Fprintf(w, "位置: %s\n", asset.Location)
197		fmt.Fprintf(w, "当前状态: %s\n", asset.Status)
