199	}
200	
201	func cmdList(args []string, w io.Writer) error {
202		var opts cmdOptions
203		fs := newFlagSet("list", &opts)
204		if err := parseFlags(fs, args); err != nil {
205			return err
206		}
207		s, err := openStore(opts.dataDir)
208		if err != nil {
209			return err
210		}
