1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"math"
9		"os"
10		"path/filepath"
11		"sort"
12		"strconv"
13		"strings"
14		"time"
15	)
16	
17	// 资产状态、工单状态与履历类型。
18	const (
19		statusAvailable = "可用"
20		statusRepairing = "维修中"
21		ticketOpen      = "未关闭"
22		ticketClosed    = "已关闭"
23	
24		eventReport = "报修"
25		eventClose  = "关闭"
26	
27		storeVersion = 1
28		dataFileName = "caretrack.json"
29	)
30	
31	var (
32		errNotFound = errors.New("not found")
33		errConflict = errors.New("conflict")
34	)
35	
36	// Asset 为登记的设备资产，ID 即企业资产编号。
37	type Asset struct {
38		ID       string `json:"id"`
39		Name     string `json:"name"`
40		Location string `json:"location"`
41		Status   string `json:"status"`
42	}
43	
44	// Ticket 为维修工单。
45	type Ticket struct {
46		ID          string `json:"id"`
47		AssetID     string `json:"asset_id"`
48		Description string `json:"description"`
49		RequestID   string `json:"request_id"`
50		Status      string `json:"status"`
51		Result      string `json:"result,omitempty"`
52		CreatedAt   string `json:"created_at"`
53		ClosedAt    string `json:"closed_at,omitempty"`
54	}
55	
56	// Event 为履历条目（报修/关闭），Seq 决定操作发生顺序。
57	type Event struct {
58		Seq      int       `json:"-"`
59		AssetID  string    `json:"-"`
60		TicketID string    `json:"-"`
61		Kind     string    `json:"-"`
62		Content  string    `json:"-"`
63		Time     time.Time `json:"-"`
64	}
65	
66	// eventJSON 与 Event 对应，时间以 RFC3339 文本持久化。
67	type eventJSON struct {
68		Seq      int    `json:"seq"`
69		AssetID  string `json:"asset_id"`
70		TicketID string `json:"ticket_id"`
71		Kind     string `json:"kind"`
72		Content  string `json:"content"`
73		Time     string `json:"time"`
74	}
75	
76	func (e Event) toJSON() eventJSON {
77		return eventJSON{
78			Seq: e.Seq, AssetID: e.AssetID, TicketID: e.TicketID,
79			Kind: e.Kind, Content: e.Content, Time: e.Time.Format(time.RFC3339),
80		}
81	}
82	
83	func (e eventJSON) toEvent() (Event, error) {
84		t, err := time.Parse(time.RFC3339, e.Time)
85		if err != nil {
86			return Event{}, fmt.Errorf("履历时间格式无效 %q: %w", e.Time, err)
87		}
88		return Event{
89			Seq: e.Seq, AssetID: e.AssetID, TicketID: e.TicketID,
90			Kind: e.Kind, Content: e.Content, Time: t,
91		}, nil
92	}
93	
94	// requestBinding 记录请求标识与具体报修的绑定，用于去重与冲突拒绝；
95	// 它既不是资产编号也不是工单编号。
96	type requestBinding struct {
97		RequestID   string `json:"request_id"`
98		AssetID     string `json:"asset_id"`
99		Description string `json:"description"`
100		TicketID    string `json:"ticket_id"`
101	}
102	
103	// storeData 是一次成功写操作共同生效的完整业务数据。
104	type storeData struct {
105		Version       int              `json:"version"`
106		Assets        []*Asset         `json:"assets"`
107		Tickets       []*Ticket        `json:"tickets"`
108		Events        []Event          `json:"-"`
109		EventsJSON    []eventJSON      `json:"events"`
110		Requests      []requestBinding `json:"requests"`
111		NextTicketSeq int              `json:"next_ticket_seq"`
112	}
113	
114	type store struct {
115		dir  string
116		data *storeData
117		now  func() time.Time
118	}
119	
120	func newStoreData() *storeData {
121		return &storeData{
122			Version:       storeVersion,
123			Assets:        []*Asset{},
124			Tickets:       []*Ticket{},
125			Events:        []Event{},
126			EventsJSON:    []eventJSON{},
127			Requests:      []requestBinding{},
128			NextTicketSeq: 1,
129		}
130	}
131	
132	// openStore 打开数据目录：目录/文件不存在时视为空库（首次保存时初始化）；
133	// 已有文件为空或无法解析时报告错误并保留原文件，绝不当空库覆盖。
134	func openStore(dir string) (*store, error) {
135		path := filepath.Join(dir, dataFileName)
136		raw, err := os.ReadFile(path)
137		if err != nil {
138			if errors.Is(err, os.ErrNotExist) {
139				return &store{dir: dir, data: newStoreData(), now: time.Now}, nil
140			}
141			return nil, fmt.Errorf("读取数据文件失败: %w", err)
142		}
143		if len(bytes.TrimSpace(raw)) == 0 {
144			return nil, fmt.Errorf("数据文件 %s 已损坏：文件为空（原文件已保留，未做任何修改）", path)
145		}
146		var d storeData
147		if err := json.Unmarshal(raw, &d); err != nil {
148			return nil, fmt.Errorf("数据文件 %s 已损坏：%w（原文件已保留，未做任何修改）", path, err)
149		}
150		if d.EventsJSON != nil {
151			d.Events = make([]Event, len(d.EventsJSON))
152			for i, ej := range d.EventsJSON {
153				ev, err := ej.toEvent()
154				if err != nil {
155					return nil, fmt.Errorf("数据文件 %s 已损坏：%w（原文件已保留，未做任何修改）", path, err)
156				}
157				d.Events[i] = ev
158			}
159		}
160		if err := validateData(&d); err != nil {
161			return nil, fmt.Errorf("数据文件 %s 内容相互矛盾：%w（原文件已保留，未做任何修改）", path, err)
162		}
163		return &store{dir: dir, data: &d, now: time.Now}, nil
164	}
165	
166	// parseTicketSeq 解析 T 加补零正整数序号形式的工单编号，返回序号。
167	// 编号必须与 fmt.Sprintf("T%04d", n)（n ≥ 1）完全一致，否则视为非法。
168	func parseTicketSeq(id string) (int, bool) {
169		if !strings.HasPrefix(id, "T") {
170			return 0, false
171		}
172		n, err := strconv.Atoi(id[1:])
173		if err != nil || n < 1 {
174			return 0, false
175		}
176		if fmt.Sprintf("T%04d", n) != id {
177			return 0, false
178		}
179		return n, true
180	}
181	
182	// validateData 校验整份业务数据的内部一致性。任何矛盾都会返回指明问题类别
183	// （计数器/请求绑定/状态/履历）的错误；调用方必须拒绝查询与写入并保留原文件。
184	// 不做任何修复：不补字段、不重编号、不删除记录。
185	func validateData(d *storeData) error {
186		if d.Version != storeVersion {
187			return fmt.Errorf("不支持的数据版本 %d", d.Version)
188		}
189		if d.Assets == nil || d.Tickets == nil || d.Requests == nil || d.EventsJSON == nil || d.Events == nil {
190			return errors.New("缺少必要的数据段")
191		}
192		assets := map[string]*Asset{}
193		for _, a := range d.Assets {
194			if a == nil || a.ID == "" || a.Name == "" || a.Location == "" {
195				return errors.New("数据矛盾：存在字段不完整的资产记录")
196			}
197			if a.Status != statusAvailable && a.Status != statusRepairing {
198				return fmt.Errorf("状态矛盾：资产 %s 状态无效 %q", a.ID, a.Status)
199			}
200			if assets[a.ID] != nil {
201				return fmt.Errorf("数据矛盾：资产编号 %s 重复", a.ID)
202			}
203			assets[a.ID] = a
204		}
205		tickets := map[string]*Ticket{}
206		maxTicketSeq := 0
207		for _, t := range d.Tickets {
208			if t == nil || t.ID == "" || t.AssetID == "" || t.RequestID == "" || t.Description == "" || t.CreatedAt == "" {
209				return errors.New("数据矛盾：存在字段不完整的工单记录（工单描述不能为空）")
210			}
211			n, ok := parseTicketSeq(t.ID)
212			if !ok {
213				return fmt.Errorf("计数器矛盾：工单编号 %q 不是 T 加补零正整数序号的形式", t.ID)
214			}
215			if n > maxTicketSeq {
216				maxTicketSeq = n
217			}
218			if t.Status != ticketOpen && t.Status != ticketClosed {
219				return fmt.Errorf("状态矛盾：工单 %s 状态无效 %q", t.ID, t.Status)
220			}
221			if assets[t.AssetID] == nil {
222				return fmt.Errorf("数据矛盾：工单 %s 引用了不存在的资产 %s", t.ID, t.AssetID)
223			}
224			if t.Status == ticketClosed && (t.Result == "" || t.ClosedAt == "") {
225				return fmt.Errorf("状态矛盾：已关闭工单 %s 缺少维修结果或关闭时间", t.ID)
226			}
227			if t.Status == ticketOpen && (t.Result != "" || t.ClosedAt != "") {
228				return fmt.Errorf("状态矛盾：未关闭工单 %s 不应带有维修结果或关闭时间", t.ID)
229			}
230			if tickets[t.ID] != nil {
231				return fmt.Errorf("数据矛盾：工单编号 %s 重复", t.ID)
232			}
233			tickets[t.ID] = t
234		}
235		// 下一工单序号必须为正并大于全部已用序号（允许有间隔）。
236		if d.NextTicketSeq < 1 || d.NextTicketSeq <= maxTicketSeq {
237			return fmt.Errorf("计数器矛盾：下一工单序号 %d 必须为正并大于全部已用序号（当前最大 %d）",
238				d.NextTicketSeq, maxTicketSeq)
239		}
240		// 请求绑定：每张工单恰有一条绑定，且请求标识、资产、描述、工单编号完全一致。
241		boundReq := map[string]bool{}
242		boundTicket := map[string]bool{}
243		for _, r := range d.Requests {
244			if r.RequestID == "" || r.AssetID == "" || r.Description == "" || r.TicketID == "" {
245				return errors.New("请求绑定矛盾：存在字段不完整的请求绑定记录")
246			}
247			if boundReq[r.RequestID] {
248				return fmt.Errorf("请求绑定矛盾：请求标识 %s 被绑定多次", r.RequestID)
249			}
250			boundReq[r.RequestID] = true
251			t := tickets[r.TicketID]
252			if t == nil {
253				return fmt.Errorf("请求绑定矛盾：请求标识 %s 绑定的工单 %s 不存在", r.RequestID, r.TicketID)
254			}
255			if t.RequestID != r.RequestID {
256				return fmt.Errorf("请求绑定矛盾：工单 %s 的请求标识为 %s，绑定记录却来自请求 %s",
257					r.TicketID, t.RequestID, r.RequestID)
258			}
259			if r.AssetID != t.AssetID || r.Description != t.Description {
260				return fmt.Errorf("请求绑定矛盾：请求标识 %s 绑定的资产编号或故障描述与工单 %s 不一致",
261					r.RequestID, t.ID)
262			}
263			boundTicket[r.TicketID] = true
264		}
265		for _, t := range d.Tickets {
266			if !boundTicket[t.ID] {
267				return fmt.Errorf("请求绑定矛盾：工单 %s 缺少对应的报修请求绑定", t.ID)
268			}
269		}
270		// 状态：每项资产最多一张未关闭工单，有则“维修中”，无则“可用”。
271		openCount := map[string]int{}
272		for _, t := range d.Tickets {
273			if t.Status == ticketOpen {
274				openCount[t.AssetID]++
275			}
276		}
277		for _, a := range d.Assets {
278			c := openCount[a.ID]
279			if c > 1 {
280				return fmt.Errorf("状态矛盾：资产 %s 有 %d 张未关闭工单，最多允许一张", a.ID, c)
281			}
282			want := statusAvailable
283			if c == 1 {
284				want = statusRepairing
285			}
286			if a.Status != want {
287				return fmt.Errorf("状态矛盾：资产 %s 有 %d 张未关闭工单，状态应为 %s，实际为 %s",
288					a.ID, c, want, a.Status)
289			}
290		}
291		// 履历：序号全库唯一且为正整数；归属、内容与工单一致。
292		seenSeq := map[int]bool{}
293		reportSeq := map[string]int{}
294		closeSeq := map[string]int{}
295		reportCount := map[string]int{}
296		closeCount := map[string]int{}
297		for i := range d.Events {
298			e := &d.Events[i]
299			if e.Seq < 1 {
300				return fmt.Errorf("履历矛盾：履历序号 %d 不是正整数", e.Seq)
301			}
302			if seenSeq[e.Seq] {
303				return fmt.Errorf("履历矛盾：履历序号 %d 重复", e.Seq)
304			}
305			seenSeq[e.Seq] = true
306			if e.AssetID == "" || e.TicketID == "" || e.Kind == "" || e.Content == "" {
307				return errors.New("履历矛盾：存在字段不完整的履历记录")
308			}
309			t := tickets[e.TicketID]
310			if t == nil || assets[e.AssetID] == nil {
311				return fmt.Errorf("履历矛盾：履历序号 %d 引用了不存在的资产或工单", e.Seq)
312			}
313			if e.AssetID != t.AssetID {
314				return fmt.Errorf("履历矛盾：履历序号 %d 的资产 %s 与工单 %s 归属的资产 %s 不一致",
315					e.Seq, e.AssetID, t.ID, t.AssetID)
316			}
317			switch e.Kind {
318			case eventReport:
319				if e.Content != t.Description {
320					return fmt.Errorf("履历矛盾：工单 %s 的报修履历内容与故障描述不一致", t.ID)
321				}
322				reportCount[t.ID]++
323				reportSeq[t.ID] = e.Seq
324			case eventClose:
325				if e.Content != t.Result {
326					return fmt.Errorf("履历矛盾：工单 %s 的关闭履历内容与维修结果不一致", t.ID)
327				}
328				closeCount[t.ID]++
329				closeSeq[t.ID] = e.Seq
330			default:
331				return fmt.Errorf("履历矛盾：履历序号 %d 的事件类型无效 %q", e.Seq, e.Kind)
332			}
333		}
334		for _, t := range d.Tickets {
335			if reportCount[t.ID] != 1 {
336				return fmt.Errorf("履历矛盾：工单 %s 应有恰一条报修履历，实际 %d 条", t.ID, reportCount[t.ID])
337			}
338			if t.Status == ticketClosed {
339				if closeCount[t.ID] != 1 {
340					return fmt.Errorf("履历矛盾：已关闭工单 %s 应有恰一条关闭履历，实际 %d 条", t.ID, closeCount[t.ID])
341				}
342				if closeSeq[t.ID] <= reportSeq[t.ID] {
343					return fmt.Errorf("履历矛盾：工单 %s 的关闭履历（序号 %d）不在报修履历（序号 %d）之后",
344						t.ID, closeSeq[t.ID], reportSeq[t.ID])
345				}
346			} else if closeCount[t.ID] != 0 {
347				return fmt.Errorf("履历矛盾：未关闭工单 %s 不得有关闭履历", t.ID)
348			}
349		}
350		// 按履历序号推进，重放得到的工单与资产状态须与保存的状态相符；
351		// 同一资产的上一张工单必须先关闭才可产生下一张报修。
352		sorted := make([]Event, len(d.Events))
353		copy(sorted, d.Events)
354		sort.SliceStable(sorted, func(i, j int) bool { return sorted[i].Seq < sorted[j].Seq })
355		derivedTicket := map[string]string{}
356		derivedOpen := map[string]string{}
357		for _, e := range sorted {
358			switch e.Kind {
359			case eventReport:
360				if derivedTicket[e.TicketID] != "" {
361					return fmt.Errorf("履历矛盾：工单 %s 被重复报修", e.TicketID)
362				}
363				if prev := derivedOpen[e.AssetID]; prev != "" {
364					return fmt.Errorf("履历矛盾：资产 %s 的上一张工单 %s 尚未关闭就产生了工单 %s 的报修",
365						e.AssetID, prev, e.TicketID)
366				}
367				derivedTicket[e.TicketID] = ticketOpen
368				derivedOpen[e.AssetID] = e.TicketID
369			case eventClose:
370				if derivedTicket[e.TicketID] != ticketOpen {
371					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现关闭履历", e.TicketID)
372				}
373				derivedTicket[e.TicketID] = ticketClosed
374				delete(derivedOpen, e.AssetID)
375			}
376		}
377		for _, t := range d.Tickets {
378			if derivedTicket[t.ID] != t.Status {
379				return fmt.Errorf("状态矛盾：按履历推进得到工单 %s 状态为 %s，与保存的 %s 不符",
380					t.ID, derivedTicket[t.ID], t.Status)
381			}
382		}
383		for _, a := range d.Assets {
384			want := statusAvailable
385			if derivedOpen[a.ID] != "" {
386				want = statusRepairing
387			}
388			if a.Status != want {
389				return fmt.Errorf("状态矛盾：按履历推进得到资产 %s 状态为 %s，与保存的 %s 不符",
390					a.ID, want, a.Status)
391			}
392		}
393		return nil
394	}
395	
396	// save 将全部业务数据一次性原子写入：先写同目录临时文件，fsync 后 rename
397	// 覆盖正式文件。写入前先校验待提交数据的一致性；校验或读写失败时原文件
398	// 保持不变，不留下部分业务变化。
399	func (s *store) save() error {
400		s.data.EventsJSON = make([]eventJSON, len(s.data.Events))
401		for i, e := range s.data.Events {
402			s.data.EventsJSON[i] = e.toJSON()
403		}
404		if err := validateData(s.data); err != nil {
405			return fmt.Errorf("待保存数据未通过一致性检查：%w（未写入任何数据）", err)
406		}
407		var buf bytes.Buffer
408		enc := json.NewEncoder(&buf)
409		enc.SetIndent("", "  ")
410		if err := enc.Encode(s.data); err != nil {
411			return fmt.Errorf("编码数据失败: %w", err)
412		}
413		if err := os.MkdirAll(s.dir, 0o755); err != nil {
414			return fmt.Errorf("创建数据目录失败: %w", err)
415		}
416		path := filepath.Join(s.dir, dataFileName)
417		tmp, err := os.CreateTemp(s.dir, ".caretrack-*.tmp")
418		if err != nil {
419			return fmt.Errorf("创建临时数据文件失败: %w", err)
420		}
421		tmpName := tmp.Name()
422		abort := func(err error) error {
423			_ = tmp.Close()
424			_ = os.Remove(tmpName)
425			return err
426		}
427		if _, err := tmp.Write(buf.Bytes()); err != nil {
428			abort(nil)
429			return fmt.Errorf("写入数据失败: %w", err)
430		}
431		if err := tmp.Sync(); err != nil {
432			abort(nil)
433			return fmt.Errorf("写入数据失败: %w", err)
434		}
435		if err := tmp.Close(); err != nil {
436			_ = os.Remove(tmpName)
437			return fmt.Errorf("写入数据失败: %w", err)
438		}
439		if err := os.Rename(tmpName, path); err != nil {
440			_ = os.Remove(tmpName)
441			return fmt.Errorf("保存数据失败: %w", err)
442		}
443		return nil
444	}
445	
446	func (s *store) findAsset(id string) *Asset {
447		for _, a := range s.data.Assets {
448			if a.ID == id {
449				return a
450			}
451		}
452		return nil
453	}
454	
455	func (s *store) findTicket(id string) *Ticket {
456		for _, t := range s.data.Tickets {
457			if t.ID == id {
458				return t
459			}
460		}
461		return nil
462	}
463	
464	func (s *store) findRequest(requestID string) *requestBinding {
465		for i := range s.data.Requests {
466			if s.data.Requests[i].RequestID == requestID {
467				return &s.data.Requests[i]
468			}
469		}
470		return nil
471	}
472	
473	func (s *store) openTicketOf(assetID string) *Ticket {
474		for _, t := range s.data.Tickets {
475			if t.AssetID == assetID && t.Status == ticketOpen {
476				return t
477			}
478		}
479		return nil
480	}
481	
482	func (s *store) eventsOf(assetID string) []Event {
483		out := make([]Event, 0)
484		for _, e := range s.data.Events {
485			if e.AssetID == assetID {
486				out = append(out, e)
487			}
488		}
489		sort.SliceStable(out, func(i, j int) bool { return out[i].Seq < out[j].Seq })
490		return out
491	}
492	
493	// nextEventSeq 返回下一条履历应使用的全库唯一正整数序号；计数器耗尽时报错。
494	func (s *store) nextEventSeq() (int, error) {
495		maxSeq := 0
496		for _, e := range s.data.Events {
497			if e.Seq > maxSeq {
498				maxSeq = e.Seq
499			}
500		}
501		if maxSeq == math.MaxInt {
502			return 0, fmt.Errorf("%w: 履历序号计数器已耗尽，无法追加履历", errConflict)
503		}
504		return maxSeq + 1, nil
505	}
506	
507	// appendEvent 以给定序号追加履历。调用方须先通过 nextEventSeq 取得序号，
508	// 确保任何失败路径都不会在部分变更后才报错。
509	func (s *store) appendEvent(seq int, assetID, ticketID, kind, content string) {
510		s.data.Events = append(s.data.Events, Event{
511			Seq:      seq,
512			AssetID:  assetID,
513			TicketID: ticketID,
514			Kind:     kind,
515			Content:  content,
516			Time:     s.now(),
517		})
518	}
519	
520	func (s *store) registerAsset(id, name, location string) (*Asset, error) {
521		if s.findAsset(id) != nil {
522			return nil, fmt.Errorf("%w: 资产编号 %q 已存在", errConflict, id)
523		}
524		a := &Asset{ID: id, Name: name, Location: location, Status: statusAvailable}
525		s.data.Assets = append(s.data.Assets, a)
526		return a, nil
527	}
528	
529	// report 创建报修工单。返回 (工单, 是否为去重重放, 错误)。
530	// 所有失败路径都不修改任何业务数据，也不会绑定新的请求标识。
531	func (s *store) report(assetID, description, requestID string) (*Ticket, bool, error) {
532		// 已有绑定：相同资产+描述 => 返回原工单（无论其是否已关闭、是否已有新工单）；
533		// 资产或描述不同 => 拒绝。
534		if r := s.findRequest(requestID); r != nil {
535			if r.AssetID != assetID || r.Description != description {
536				return nil, false, fmt.Errorf(
537					"%w: 请求标识 %q 已用于资产 %q 的另一笔报修，不能搭配不同的资产编号或故障描述",
538					errConflict, requestID, r.AssetID)
539			}
540			t := s.findTicket(r.TicketID)
541			if t == nil {
542				return nil, false, fmt.Errorf("数据内部错误：请求标识 %q 绑定的工单不存在", requestID)
543			}
544			return t, true, nil
545		}
546	
547		asset := s.findAsset(assetID)
548		if asset == nil {
549			return nil, false, fmt.Errorf("%w: 未知资产编号 %q", errNotFound, assetID)
550		}
551		if t := s.openTicketOf(assetID); t != nil {
552			return nil, false, fmt.Errorf("%w: 资产 %s 已有未关闭工单 %s", errConflict, assetID, t.ID)
553		}
554		// 先确认编号与履历计数器都能推进，再修改任何业务数据：
555		// 编号耗尽时拒绝新报修，不消耗编号，也不绑定请求标识。
556		seq := s.data.NextTicketSeq
557		if seq < 1 || seq == math.MaxInt {
558			return nil, false, fmt.Errorf("%w: 工单编号计数器已耗尽，无法分配新工单编号", errConflict)
559		}
560		eventSeq, err := s.nextEventSeq()
561		if err != nil {
562			return nil, false, err
563		}
564		t := &Ticket{
565			ID:          fmt.Sprintf("T%04d", seq),
566			AssetID:     assetID,
567			Description: description,
568			RequestID:   requestID,
569			Status:      ticketOpen,
570			CreatedAt:   s.now().Format(time.RFC3339),
571		}
572		s.data.NextTicketSeq = seq + 1
573		s.data.Tickets = append(s.data.Tickets, t)
574		s.data.Requests = append(s.data.Requests, requestBinding{
575			RequestID:   requestID,
576			AssetID:     assetID,
577			Description: description,
578			TicketID:    t.ID,
579		})
580		asset.Status = statusRepairing
581		s.appendEvent(eventSeq, assetID, t.ID, eventReport, description)
582		return t, false, nil
583	}
584	
585	// closeTicket 关闭未关闭工单并把资产恢复为可用。
586	// 失败路径不修改任何业务数据。
587	func (s *store) closeTicket(ticketID, result string) (*Ticket, *Asset, error) {
588		t := s.findTicket(ticketID)
589		if t == nil {
590			return nil, nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
591		}
592		if t.Status != ticketOpen {
593			return nil, nil, fmt.Errorf("%w: 工单 %s 已关闭，不能重复关闭", errConflict, ticketID)
594		}
595		asset := s.findAsset(t.AssetID)
596		if asset == nil {
597			return nil, nil, fmt.Errorf("数据内部错误：工单 %s 引用的资产不存在", ticketID)
598		}
599		eventSeq, err := s.nextEventSeq()
600		if err != nil {
601			return nil, nil, err
602		}
603		t.Status = ticketClosed
604		t.Result = result
605		t.ClosedAt = s.now().Format(time.RFC3339)
606		asset.Status = statusAvailable
607		s.appendEvent(eventSeq, asset.ID, t.ID, eventClose, result)
608		return t, asset, nil
609	}
610

