func TestCancelCommand(t *testing.T) {
	dir := t.TempDir()
	var out, errBuf bytes.Buffer
	run := func(args ...string) (int, string, string) {
		out.Reset()
		errBuf.Reset()
		full := append([]string{args[0], "--data-dir", dir}, args[1:]...)
		code := run2(full, &out, &errBuf)
		return code, out.String(), errBuf.String()
	}
	_ = run

	// 准备数据。
	if code := run2([]string{"register", "--data-dir", dir, "--asset-id", "EQ-1", "--name", "打印机", "--location", "一楼"}, &out, &errBuf); code != 0 {
		t.Fatalf("register: %s", errBuf.String())
	}
	out.Reset()
	if code := run2([]string{"report", "--data-dir", dir, "--asset-id", "EQ-1", "--description", "卡纸", "--request-id", "req-1"}, &out, &errBuf); code != 0 {
		t.Fatalf("report: %s", errBuf.String())
	}

	// 缺少取消理由：退出码 2。
	out.Reset()
	errBuf.Reset()
	if code := run2([]string{"cancel", "--data-dir", dir, "--ticket-id", "T0001"}, &out, &errBuf); code != 2 {
		t.Fatalf("空理由退出码 = %d，应为 2（%s）", code, errBuf.String())
	}
	// 未知工单：退出码 1。
	out.Reset()
	errBuf.Reset()
	if code := run2([]string{"cancel", "--data-dir", dir, "--ticket-id", "T9999", "--reason", "误报"}, &out, &errBuf); code != 1 {
		t.Fatalf("未知工单退出码 = %d，应为 1（%s）", code, errBuf.String())
	}
	if !strings.Contains(errBuf.String(), "未知工单编号") {
		t.Fatalf("应说明未知工单，得到 %s", errBuf.String())
	}
	// 成功取消：输出原工单编号与已取消状态。
	out.Reset()
	errBuf.Reset()
	if code := run2([]string{"cancel", "--data-dir", dir, "--ticket-id", "T0001", "--reason", "误报"}, &out, &errBuf); code != 0 {
		t.Fatalf("取消应成功: %s", errBuf.String())
	}
	if !strings.Contains(out.String(), "T0001") || !strings.Contains(out.String(), "已取消") {
		t.Fatalf("成功输出应包含工单编号与已取消状态: %s", out.String())
	}
	// 详情中未关闭工单显示“无”。
	out.Reset()
	errBuf.Reset()
	if code := run2([]string{"detail", "--data-dir", dir, "--asset-id", "EQ-1"}, &out, &errBuf); code != 0 {
		t.Fatalf("detail: %s", errBuf.String())
	}
	if !strings.Contains(out.String(), "未关闭工单: 无") || !strings.Contains(out.String(), "可用") {
		t.Fatalf("取消后详情异常: %s", out.String())
	}
	// 履历包含取消事件与理由。
	out.Reset()
	errBuf.Reset()
	if code := run2([]string{"history", "--data-dir", dir, "--asset-id", "EQ-1"}, &out, &errBuf); code != 0 {
		t.Fatalf("history: %s", errBuf.String())
	}
	if !strings.Contains(out.String(), "取消") || !strings.Contains(out.String(), "误报") ||
		!strings.Contains(out.String(), "T0001") {
		t.Fatalf("履历应包含取消事件: %s", out.String())
	}
	// 重复取消：退出码 1 并说明原因。
	out.Reset()
	errBuf.Reset()
	if code := run2([]string{"cancel", "--data-dir", dir, "--ticket-id", "T0001", "--reason", "再次"}, &out, &errBuf); code != 1 {
		t.Fatalf("重复取消退出码 = %d，应为 1", code)
	}
	if !strings.Contains(errBuf.String(), "已取消") {
		t.Fatalf("应说明已取消，得到 %s", errBuf.String())
	}
	// 已取消工单不能关闭。
	out.Reset()
	errBuf.Reset()
	if code := run2([]string{"close", "--data-dir", dir, "--ticket-id", "T0001", "--repair-result", "结果"}, &out, &errBuf); code != 1 {
		t.Fatalf("已取消工单关闭退出码 = %d，应为 1", code)
	}
	// 取消后可重新报修。
	out.Reset()
	errBuf.Reset()
	if code := run2([]string{"report", "--data-dir", dir, "--asset-id", "EQ-1", "--description", "无法开机", "--request-id", "req-2"}, &out, &errBuf); code != 0 {
		t.Fatalf("取消后应可重新报修: %s", errBuf.String())
	}
	if !strings.Contains(out.String(), "T0002") {
		t.Fatalf("新工单应为 T0002: %s", out.String())
	}
	// 旧请求重放返回已取消的原工单，不影响新单。
	out.Reset()
	errBuf.Reset()
	if code := run2([]string{"report", "--data-dir", dir, "--asset-id", "EQ-1", "--description", "卡纸", "--request-id", "req-1"}, &out, &errBuf); code != 0 {
		t.Fatalf("旧请求重放应成功: %s", errBuf.String())
	}
	if !strings.Contains(out.String(), "T0001") || !strings.Contains(out.String(), "已取消") {
		t.Fatalf("重放应返回已取消的 T0001: %s", out.String())
	}
}

// run2 是 run 的薄封装，避免测试内变量遮蔽。
func run2(args []string, stdout, stderr *bytes.Buffer) int {
	return run(args, stdout, stderr)
}

